import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"模型层 core","description":"","frontmatter":{},"headers":[],"relativePath":"reference/core.md","filePath":"reference/core.md","lastUpdated":1792293807000}`),a={name:`reference/core.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="模型层-core" tabindex="-1">模型层 core <a class="header-anchor" href="#模型层-core" aria-label="Permalink to “模型层 core”">​</a></h1><p><code>@xihan-flow/core</code> 是纯 TypeScript 的模型层：流程定义的类型、读入检查、校验、编辑操作、连线几何、节点类型登记与扩展合并，不依赖 DOM，浏览器、Node.js 与其它 JavaScript 运行环境里都能用。流程定义的字段见<a href="./schema">流程定义类型</a>，问题码见<a href="./issues">问题码</a>。下表按源码模块列出全部导出。</p><h2 id="全部导出" tabindex="-1">全部导出 <a class="header-anchor" href="#全部导出" aria-label="Permalink to “全部导出”">​</a></h2><h3 id="extensions" tabindex="-1">extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to “extensions”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>createFlowModel</code></td><td>函数</td><td>合出流程模型：内置扩展 FLOW_CORE_EXTENSION 在前，extensions 按顺序在后。</td></tr><tr><td><code>FLOW_CORE_EXTENSION</code></td><td>常量</td><td>内置扩展：连线的标签与虚线。</td></tr><tr><td><code>FLOW_EXTENSION_SPACES</code></td><td>常量</td><td>流程各层扩展共用的名字空间：节点类型、连线属性路径与流程定义级属性路径。</td></tr><tr><td><code>FlowCoreExtension</code></td><td>接口</td><td>流程 core 层的扩展：节点类型、连线属性、流程定义级属性、编辑方式与规则。</td></tr><tr><td><code>FlowModel</code></td><td>接口</td><td>一组扩展合出的流程模型：节点类型、连线与流程定义级属性、编辑方式。</td></tr><tr><td><code>FlowRuleContext</code></td><td>接口</td><td>规则拿到的上下文：合并后的节点类型。</td></tr><tr><td><code>patchExtensionData</code></td><td>函数</td><td>某个扩展的数据写进对象原有的 extensions 后的新值，交给 updateNode / updateEdge / updateDocument 的 patch.extensions：别的扩展的数据原样保留；data 为 undefined 时去掉这一块，去完为空时为 null（即删掉 extensions 字段）。</td></tr></tbody></table><h3 id="geometry" tabindex="-1">geometry <a class="header-anchor" href="#geometry" aria-label="Permalink to “geometry”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>computeEdgeGeometry</code></td><td>函数</td><td>求全部连线的折线：带折点的连线依次穿过折点，其余交给 route；两端都以端口位置为起止。</td></tr><tr><td><code>FlowEdgeAnchor</code></td><td>接口</td><td>连线的一端：端口位置与离开（起点）或进入（终点）节点的那一边。</td></tr><tr><td><code>FlowEdgeGeometry</code></td><td>接口</td><td>一条连线的几何；端点解析不出时 points 为空、anchored 为 false。</td></tr><tr><td><code>FlowEdgeRouter</code></td><td>类型</td><td>路由器：给出从起点锚点到终点锚点的完整折线（含两端）。</td></tr><tr><td><code>FlowRouteRequest</code></td><td>接口</td><td>路由器的输入：两端锚点与要绕开的节点框。</td></tr><tr><td><code>resolveEdgeAnchor</code></td><td>函数</td><td>解析连线一端的锚点；节点不存在、类型未知或没有可用端口时返回 undefined。</td></tr></tbody></table><h3 id="issues" tabindex="-1">issues <a class="header-anchor" href="#issues" aria-label="Permalink to “issues”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>FlowEdgeEnd</code></td><td>类型</td><td>连线的一端。</td></tr><tr><td><code>FlowIssue</code></td><td>类型</td><td>一条问题：问题码、从文档根算起的路径、所在对象（节点为 { kind: &#39;node&#39;, id }，连线为 { kind: &#39;edge&#39;, id }）、严重程度与参数，不带文案。</td></tr><tr><td><code>FlowIssueCode</code></td><td>类型</td><td>全部问题码。</td></tr><tr><td><code>FlowSchemaIssueCode</code></td><td>类型</td><td>读取未知输入时的结构问题码：通用问题码之外只有版本不受支持。</td></tr><tr><td><code>FlowValidationIssueCode</code></td><td>类型</td><td>按节点类型登记表校验文档时的问题码；required 与取值问题码来自节点属性检查。</td></tr></tbody></table><h3 id="operations" tabindex="-1">operations <a class="header-anchor" href="#operations" aria-label="Permalink to “operations”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>applyOperation</code></td><td>函数</td><td>应用一个编辑操作，返回新文档与逆操作，不修改输入文档；未改动的节点与连线沿用原引用。</td></tr><tr><td><code>applyOperations</code></td><td>函数</td><td>依次应用一组操作；逆操作为各操作逆操作按反序拼接。</td></tr><tr><td><code>FlowDocumentPatch</code></td><td>接口</td><td>文档字段补丁：缺省表示不变，null 表示删除该字段。</td></tr><tr><td><code>FlowEdgePatch</code></td><td>接口</td><td>连线字段补丁：缺省表示不变，null 表示删除该字段。</td></tr><tr><td><code>FlowNodePatch</code></td><td>接口</td><td>节点字段补丁：缺省表示不变，null 表示删除该字段。</td></tr><tr><td><code>FlowNodePosition</code></td><td>接口</td><td>节点的新位置。</td></tr><tr><td><code>FlowOperation</code></td><td>类型</td><td>编辑操作；所有操作都是纯 JSON。</td></tr><tr><td><code>FlowOperationError</code></td><td>类</td><td>操作无法应用时抛出的错误；文档保持不变。</td></tr><tr><td><code>FlowOperationErrorCode</code></td><td>类型</td><td>操作失败原因。</td></tr><tr><td><code>FlowOperationResult</code></td><td>接口</td><td>应用操作的结果：新文档与按顺序应用即可撤销的逆操作；没有带来变化时文档是传入的同一引用、逆操作为空。</td></tr><tr><td><code>FlowOperationType</code></td><td>类型</td><td>操作类型名。</td></tr></tbody></table><h3 id="read" tabindex="-1">read <a class="header-anchor" href="#read" aria-label="Permalink to “read”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>FlowReadResult</code></td><td>类型</td><td>读取结果：成功时给出规范化后的文档副本，失败时给出全部结构问题。</td></tr><tr><td><code>readDocument</code></td><td>函数</td><td>把未知输入读成文档：逐项检查字段类型、必填项与多余字段，返回不与输入共享引用的副本。</td></tr></tbody></table><h3 id="registry" tabindex="-1">registry <a class="header-anchor" href="#registry" aria-label="Permalink to “registry”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>createNode</code></td><td>函数</td><td>按节点类型新建节点：尺寸、标签与 data 取类型默认值，init 中给出的字段优先；再把属性描述的缺省值写进还没有值的路径。</td></tr><tr><td><code>createNodeTypeRegistry</code></td><td>函数</td><td>创建节点类型登记表；定义不合法时抛错。</td></tr><tr><td><code>findPort</code></td><td>函数</td><td>查找节点类型上的端口。</td></tr><tr><td><code>FlowConnectionRule</code></td><td>接口</td><td>连接约束。</td></tr><tr><td><code>FlowEdgeStyleRule</code></td><td>接口</td><td>按连线数据给的外观：when 对连线本身求值，满足时并上 style。</td></tr><tr><td><code>FlowNodeDefaults</code></td><td>接口</td><td>新建节点时的默认值。</td></tr><tr><td><code>FlowNodeInit</code></td><td>接口</td><td>新建节点的参数。</td></tr><tr><td><code>FlowNodeType</code></td><td>接口</td><td>规范化后的节点类型：端口展开为具名端口列表。</td></tr><tr><td><code>FlowNodeTypeDefinition</code></td><td>接口</td><td>节点类型定义：同时驱动物料面板、属性面板、连线约束与结构校验。</td></tr><tr><td><code>FlowNodeTypeRegistry</code></td><td>接口</td><td>节点类型登记表。</td></tr><tr><td><code>FlowPort</code></td><td>接口</td><td>规范化后的端口。</td></tr><tr><td><code>FlowPortDefinition</code></td><td>接口</td><td>具名端口定义。</td></tr><tr><td><code>FlowPortDirection</code></td><td>类型</td><td>端口方向：只入、只出或双向。</td></tr><tr><td><code>FlowPortPreset</code></td><td>类型</td><td>端口预设：in 为左侧入口 in，out 为右侧出口 out，both 为两者都有，none 为无端口。</td></tr><tr><td><code>FlowPortSide</code></td><td>类型</td><td>端口所在的节点边。</td></tr><tr><td><code>FlowPropertyControl</code></td><td>类型</td><td>节点属性的编辑方式：内建的编辑方式之外，扩展可以登记自己的种类（如受理人选择），编辑器由设计器层的扩展提供。</td></tr><tr><td><code>FlowPropertyDescriptor</code></td><td>类型</td><td>节点属性描述：path 相对节点本身，如 [&#39;data&#39;, &#39;properties&#39;, &#39;Url&#39;]、[&#39;label&#39;]。</td></tr><tr><td><code>getPortPosition</code></td><td>函数</td><td>计算端口在世界坐标系中的位置。</td></tr><tr><td><code>portAllows</code></td><td>函数</td><td>判断端口能否作为连线的指定一端：起点需可出，终点需可入。</td></tr><tr><td><code>resolveEdgeStyle</code></td><td>函数</td><td>连线此刻的外观：源节点类型的 outgoingEdgeStyles 按先后并上满足条件的，连线自己写的 style 再逐项压过；源节点类型未知时只有连线自己写的。</td></tr></tbody></table><h3 id="schema" tabindex="-1">schema <a class="header-anchor" href="#schema" aria-label="Permalink to “schema”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>createDocument</code></td><td>函数</td><td>创建空文档。</td></tr><tr><td><code>FLOW_DOCUMENT_VERSION</code></td><td>常量</td><td>当前文档 schema 版本。</td></tr><tr><td><code>FlowDocument</code></td><td>接口</td><td>流程图文档；数组顺序即绘制层级，靠后的在上层。</td></tr><tr><td><code>FlowEdge</code></td><td>接口</td><td>连线：起止端点、标签、外观、业务数据与可选折点。</td></tr><tr><td><code>FlowEdgeStyle</code></td><td>接口</td><td>连线外观。</td></tr><tr><td><code>FlowEndpoint</code></td><td>接口</td><td>连线端点：节点与可选端口。</td></tr><tr><td><code>FlowNode</code></td><td>接口</td><td>节点：左上角坐标、尺寸、可选标签与业务数据。</td></tr><tr><td><code>FlowPoint</code></td><td>接口</td><td>世界坐标系中的点。</td></tr><tr><td><code>FlowRect</code></td><td>接口</td><td>轴对齐矩形。</td></tr><tr><td><code>FlowSize</code></td><td>接口</td><td>尺寸。</td></tr></tbody></table><h3 id="validate" tabindex="-1">validate <a class="header-anchor" href="#validate" aria-label="Permalink to “validate”">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>种类</th><th>说明</th></tr></thead><tbody><tr><td><code>checkConnection</code></td><td>函数</td><td>检查在 source 与 target 之间新增一条连线是否违反端口与连接约束，返回全部问题；空数组表示允许连接。</td></tr><tr><td><code>DEFAULT_ISSUE_SEVERITY</code></td><td>常量</td><td>各问题码的缺省严重程度。</td></tr><tr><td><code>FlowConnectionCheckOptions</code></td><td>接口</td><td>连接检查选项。</td></tr><tr><td><code>FlowConnectionIssueCode</code></td><td>类型</td><td>连接检查可能给出的问题码。</td></tr><tr><td><code>FlowConnectionProblem</code></td><td>接口</td><td>一条连接问题；end 指出问题出在哪一端，自环问题不带 end。</td></tr><tr><td><code>FlowValidateOptions</code></td><td>接口</td><td>校验选项。</td></tr><tr><td><code>resolveEndpointPort</code></td><td>函数</td><td>解析端点实际连接的端口：指定了端口时按 id 查找，否则取第一个允许该端的端口。</td></tr><tr><td><code>validateDocument</code></td><td>函数</td><td>按扩展合出的流程模型校验文档结构，返回全部问题，每条都带上严重程度。</td></tr></tbody></table>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};